export const STUDIO_LOCALES = Object.freeze({ en });

export function formatStudioMessage(template, values = {}) {
    return String(template ?? '').replace(/\{([A-Za-z0-9_]+)\}/g, (match, name) =>
        Object.hasOwn(values, name) ? String(values[name]) : match,
    );
}
